for(const omit of [false,true])test('print photo failure offers targeted retry or explicit annotated omission '+omit,async()=>{
 const {p,errors}=await setup();await start(p);await p.evaluate(()=>{const c=document.createElement('canvas');c.width=100;c.height=80;for(let i=0;i<4;i++)photoBytes['print-'+i]=c.toDataURL('image/png');stored.body.healthcheckChart.images=Array.from({length:4},(_,i)=>({id:'print-'+i,kind:'ultrasound',caption:'가상 사진 '+i,imageRevision:1}));failPhoto='print-2';});await p.evaluate(()=>view.openRecord('record-1'));await p.locator('[data-step=summary]').click();const next=p.waitForEvent('popup');await p.locator('[data-action=print]').click();const popup=await next;await popup.locator('[data-retry]').waitFor();assert.match(await popup.locator('[role=status]').innerText(),/3 \/ 4/);assert.equal(await p.evaluate(()=>calls.filter(x=>x.url.includes('healthcheck-images?')).length),4);await popup.locator(omit?'[data-omit]':'[data-retry]').click();await popup.locator('h1').filter({hasText:'건강검진 결과서'}).waitFor();assert.equal(await popup.locator('figure').count(),omit?3:4);assert.equal(await p.evaluate(()=>calls.filter(x=>x.url.includes('healthcheck-images?')).length),omit?4:5);assert.equal(await p.evaluate(()=>stored.body.healthcheckChart.images.length),4);if(omit)assert.match(await popup.locator('body').innerText(),/사진 1장 불러오기 실패로 제외/);else assert.doesNotMatch(await popup.locator('body').innerText(),/실패로 제외/);assert.deepEqual(errors,[]);await popup.close();await p.close();
});

test('completed review can be unchecked and saved as amended',async()=>{
 const {p,errors}=await setup();await start(p);await p.evaluate(()=>{stored.body.healthcheckChart.clinicalStatus='complete';stored.body.healthcheckChart.reviewed=true;});await p.evaluate(()=>view.openRecord('record-1'));await p.locator('[data-step=summary]').click();await p.locator('[data-review]').uncheck();await p.locator('[data-action=save]').click();await p.waitForFunction(()=>stored.revision===2);assert.equal(await p.evaluate(()=>stored.body.healthcheckChart.clinicalStatus),'amended');assert.equal(await p.evaluate(()=>stored.body.healthcheckChart.reviewed),false);assert.deepEqual(errors,[]);await p.close();
});

test('report source grouping never attributes unknown sources to a laboratory',()=>{const api=require('../healthcheck-record.js');const d=api.blank();d.labs=[api.row({name:'BUN',value:'10',source:'LAB-A'}),api.row({name:'CREA',value:'1',source:''})];const html=api.reportHTML(d,{name:'Synthetic',species:'dog'},[]);assert.doesNotMatch(html,/<small class="group-source">LAB-A/);assert.match(html,/<td>BUN<br><small>LAB-A/);});

test('mixed specimen aliases preserve blood and urine identities and empty results',()=>{
 const h=require('../healthcheck-record.js'),date='2026-01-01';
 const results=[{name:'GLU(idexx)',value:'90',unit:'mg/dL',group:'blood'},{name:'GLUCOSE(URINE)',value:'-',unit:'mg/dL'},{name:'PROTEIN(URINE)',value:'++',unit:''},{name:'ProBnp(V200)',value:'120',unit:'pmol/L'},{name:'TT4(idexx)',value:'2',unit:'ug/dL'},{name:'%NEU(idexx)',value:'60',unit:'%'},{name:'NEU(idexx)',value:'4',unit:'K/uL'},{name:'BAND(idexx)',value:'',unit:'K/uL',reference:'0–1'},{name:'GLU',group:'요검사',value:'0',unit:'mg/dL'}];
 const rows=h.mergeLabs([],results,'append',date);assert.equal(rows.length,8);assert.equal(rows.filter(r=>h.labTab(r)==='urine').length,3);assert.equal(rows.find(r=>r.name==='요당').value,'-');assert.equal(rows.find(r=>r.name==='%NEU').group,'CBC · 혈구검사');assert.equal(rows.find(r=>r.name==='TOTAL T4').group,'호르몬검사');assert.equal(rows.find(r=>r.name==='PROBNP').group,'심장표지자');
 const merged=h.mergeLabs([rows[0]],[{name:'GLU',group:'urine',value:'2',unit:'mg/dL'}],'replace',date);assert.equal(merged.length,2);assert.equal(merged[0].value,'90');assert.equal(merged[1].name,'요당');
});
